\newcommand{\Bnd}{B(n,d)}

\title{Tightness of the Isolation-Lemma Region Bound\\ for Arbitrary Edge Offsets}
\author{Aristotle}
\date{July 12, 2026}

\begin{document}
\maketitle

\begin{abstract}
The Isolation Lemma asserts that a random weight assignment to the elements of a
ground set makes the minimum-weight member of any set system unique with good
probability. Behind this probabilistic statement lies an exact combinatorial
quantity: for an inclusion-free hypergraph $H$ on $n$ vertices and integer weights
drawn from $\{0,\dots,d-1\}$, the number of \emph{isolating} assignments (those with
a unique minimum-weight edge) is at least the \emph{region bound}
$B(n,d) = n\sum_{j=0}^{d-1} j^{\,n-1}$. It is known that the singleton hypergraph
(all $1$-element edges) attains this bound exactly with zero offsets. We deepen this
picture in two directions. First, we refute the natural \emph{general tightness
conjecture}: it is \emph{not} true that every inclusion-free hypergraph can be made
extremal by choosing suitable real edge offsets. A single-edge hypergraph makes
every assignment isolating for \emph{every} offset, giving an offset-independent
count of $d^n > B(n,d)$ (already $4 > 2$ at $n=d=2$). Second, we exhibit a new,
symmetric extremal witness: the co-singleton hypergraph (all $(n-1)$-element edges)
also attains $B(n,d)$ exactly with zero offsets, via a min-max reflection duality on
the weight palette. Thus the region bound has at least two symmetric extremal
families, yet tightness is a genuinely special structural property rather than a
universal one attainable by tuning.
\end{abstract}

\section{Introduction}

The Isolation Lemma of Mulmuley, Vazirani, and Vazirani is a cornerstone of
randomized computation. In its combinatorial form it concerns a \emph{hypergraph}
$H$: a family of edges, each a subset of a vertex set $V=\{1,\dots,n\}$. A
\emph{weight assignment} $w:V\to\{0,\dots,d-1\}$ assigns to each vertex one of $d$
integer values; there are $d^n$ assignments in all. Attaching a real \emph{offset}
$f(S)$ to each edge $S$, the \emph{adjusted weight} of an edge is
\[
  W_f(S,w) = f(S) + \sum_{v\in S} w(v).
\]
The assignment $w$ is \emph{isolating} for $(H,f)$ if there is a unique edge of
minimum adjusted weight.

Two standing assumptions make the theory clean and nontrivial: $H$ is
\emph{inclusion-free} (an \emph{antichain}), meaning no edge is a subset of another;
and weights lie in the palette $\{0,\dots,d-1\}$.

A basic lower bound---the \emph{region bound}---states that every nonempty
inclusion-free hypergraph on $n$ vertices has at least
\[
  \Bnd = n\sum_{j=0}^{d-1} j^{\,n-1}
\]
isolating assignments. This quantity controls how much randomness the Isolation
Lemma requires, so understanding \emph{when it is tight} is of direct interest.

It is known that the \emph{singleton hypergraph} $H_1=\{\{v\}:v\in V\}$ attains
$\Bnd$ exactly with zero offsets. We answer the two most natural follow-up
questions: whether \emph{every} inclusion-free hypergraph can be brought to the
bound by choosing offsets (no; Section~\ref{sec:fails}), and whether other extremal
witnesses exist (yes; Section~\ref{sec:cosingleton}).

\subsection{Contributions}
\begin{enumerate}
  \item \textbf{Exact singleton count} (Theorem~\ref{thm:singleton}): the number of
        assignments in $\{0,\dots,d-1\}^n$ with a unique strict minimum vertex is
        exactly $\Bnd$.
  \item \textbf{Failure of general tightness} (Theorem~\ref{thm:fails}): there is an
        inclusion-free, nonempty hypergraph whose isolating count is $d^n$ for
        \emph{every} real offset, and $d^n\ne\Bnd$ in general.
  \item \textbf{A new extremal witness} (Theorem~\ref{thm:cosingleton}): the
        co-singleton hypergraph attains $\Bnd$ exactly with zero offsets, via a
        reflection duality (Theorem~\ref{thm:duality}).
\end{enumerate}

\section{Definitions}

Throughout, $V=\{1,\dots,n\}$ and the palette is $D=\{0,1,\dots,d-1\}$.

\begin{definition}[Hypergraph]
A \emph{hypergraph} on $V$ is a finite family $H$ of subsets (edges) of $V$.
\end{definition}

\begin{definition}[Inclusion-free]
$H$ is \emph{inclusion-free} if for all $S,T\in H$ with $S\subseteq T$ we have
$S=T$; equivalently, no edge is a proper subset of another.
\end{definition}

\begin{definition}[Weight assignment]
A \emph{weight assignment} is a map $w:V\to D$. There are $d^n$ of them.
\end{definition}

\begin{definition}[Isolating assignment]
Given offsets $f:H\to\mathbb{R}$, an assignment $w$ is \emph{isolating for $(H,f)$}
if there is a unique $S\in H$ with
$f(S)+\sum_{v\in S} w(v) \le f(T)+\sum_{v\in T} w(v)$ for all $T\in H$.
\end{definition}

\begin{definition}[Strict minimum / maximum]
$w$ \emph{has a strict minimum} if there is a vertex $i$ with $w(i)<w(j)$ for all
$j\ne i$. It \emph{has a strict maximum} if there is a vertex $i$ with $w(j)<w(i)$
for all $j\ne i$.
\end{definition}

\begin{definition}[Region bound]
$\Bnd = n\sum_{j=0}^{d-1} j^{\,n-1}$. Small values: $B(2,2)=2$, $B(3,2)=3$,
$B(2,3)=6$, $B(3,3)=15$, $B(4,3)=36$.
\end{definition}

\section{The exact singleton count}\label{sec:singleton}

For the singleton hypergraph $H_1=\{\{v\}:v\in V\}$ with zero offsets, the adjusted
weight of edge $\{v\}$ is simply $w(v)$. A unique minimum edge exists iff $w$ has a
strict minimum vertex.

\begin{lemma}[Values above a threshold]\label{lem:above}
For any $m\in D$, the number of palette values strictly greater than $m$ equals
$d-1-m$.
\end{lemma}
\begin{proof}
The values above $m$ are $m+1,\dots,d-1$, of which there are $d-1-m$.
\end{proof}

\begin{lemma}[Fiber count]\label{lem:fiber}
Fix a vertex $i$ and a value $m\in D$. The number of assignments $w$ with $w(i)=m$
and $w(j)>m$ for all $j\ne i$ is $(d-1-m)^{\,n-1}$.
\end{lemma}
\begin{proof}
Vertex $i$ is pinned to $m$. Each of the other $n-1$ vertices independently takes
one of the $d-1-m$ values above $m$ (Lemma~\ref{lem:above}), giving
$(d-1-m)^{\,n-1}$.
\end{proof}

\begin{lemma}[Winners at a fixed vertex]\label{lem:winners}
For any fixed vertex $i$, the number of assignments for which $i$ is the strict
minimum equals $\sum_{j=0}^{d-1} j^{\,n-1}$.
\end{lemma}
\begin{proof}
Partition by $m=w(i)$. By Lemma~\ref{lem:fiber} the class with $w(i)=m$ has size
$(d-1-m)^{\,n-1}$, so the total is $\sum_{m=0}^{d-1}(d-1-m)^{\,n-1}
= \sum_{j=0}^{d-1} j^{\,n-1}$ after substituting $j=d-1-m$. The count is
independent of $i$.
\end{proof}

\begin{lemma}[Disjointness]\label{lem:disjoint}
An assignment has at most one strict minimum vertex, so the events ``$i$ is the
strict minimum'' are pairwise disjoint and the set of assignments with a strict
minimum is their disjoint union.
\end{lemma}
\begin{proof}
If $i\ne i'$ were both strict minima then $w(i)<w(i')$ and $w(i')<w(i)$, a
contradiction.
\end{proof}

\begin{theorem}[Singleton tightness]\label{thm:singleton}
The number of assignments in $D^n$ with a strict minimum vertex is exactly
$n\sum_{j=0}^{d-1} j^{\,n-1} = \Bnd$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:disjoint} the strict-minimum set is the disjoint union over
$i\in V$ of the strict-min-at-$i$ sets, each of size $\sum_{j=0}^{d-1} j^{\,n-1}$
by Lemma~\ref{lem:winners}. With $n$ vertices the total is
$n\sum_{j=0}^{d-1} j^{\,n-1}=\Bnd$.
\end{proof}

\section{Failure of the general tightness conjecture}\label{sec:fails}

\begin{lemma}[Single-edge count]\label{lem:single}
Let $H=\{E\}$ consist of a single edge, and let $f$ be any offset. Then every
assignment is isolating, so the number of isolating assignments is $d^n$,
independent of $f$.
\end{lemma}
\begin{proof}
With one edge, the minimum adjusted weight is attained by $E$ alone, uniquely, since
there is no other edge to tie with. Hence all $d^n$ assignments are isolating.
\end{proof}

\begin{lemma}[Admissibility]\label{lem:adm}
A single-edge hypergraph $\{E\}$ is nonempty and inclusion-free.
\end{lemma}
\begin{proof}
Nonemptiness is immediate; inclusion-freeness is vacuous since the only pair is
$(E,E)$.
\end{proof}

\begin{theorem}[General tightness fails]\label{thm:fails}
There exist $n,d$ and a nonempty, inclusion-free hypergraph $H$ on $n$ vertices such
that for \emph{every} real offset $f$, the number of isolating assignments differs
from $\Bnd$.
\end{theorem}
\begin{proof}
Take $n=d=2$ and $H=\{\{1,2\}\}$. By Lemma~\ref{lem:adm}, $H$ is nonempty and
inclusion-free. By Lemma~\ref{lem:single} the isolating count is $d^n=4$ for every
$f$, while $B(2,2)=2\ne 4$. No offset achieves the bound.
\end{proof}

\begin{remark}
The single edge is the cleanest witness because its count is provably
offset-independent. Computation indicates the phenomenon is broader: covering
antichains such as $\{\{1,2\},\{1,3\}\}$ overshoot $\Bnd$ for every offset as well.
A formal proof quantifying over the continuum of offsets requires reducing offsets to
their finitely many order-types.
\end{remark}

\section{A new extremal witness: the co-singleton hypergraph}\label{sec:cosingleton}

\begin{definition}[Co-singleton hypergraph]
The \emph{co-singleton hypergraph} is $H_{n-1}=\{V\setminus\{v\}:v\in V\}$, the
family of all $(n-1)$-element edges.
\end{definition}

\begin{lemma}[Admissibility]\label{lem:cosing-adm}
$H_{n-1}$ is inclusion-free.
\end{lemma}
\begin{proof}
All edges have size $n-1$; equal-size sets cannot properly contain one another.
\end{proof}

\paragraph{Reduction to strict maxima.}
With zero offsets, the adjusted weight of $V\setminus\{v\}$ is
$\sum_{u\ne v} w(u) = \big(\sum_{u\in V} w(u)\big)-w(v)$. The grand total is common
to all edges, so minimizing the edge weight over $v$ is equivalent to maximizing
$w(v)$. Hence a unique minimum-weight edge exists iff $w$ has a unique strict
\emph{maximum} vertex.

\begin{theorem}[Reflection duality]\label{thm:duality}
Define $\rho:D\to D$, $\rho(x)=d-1-x$, and lift it by $(\rho\cdot w)(i)=\rho(w(i))$.
Then $w$ has a strict minimum iff $\rho\cdot w$ has a strict maximum, and
$w\mapsto\rho\cdot w$ is an involutive bijection of $D^n$.
\end{theorem}
\begin{proof}
$\rho$ is order-reversing: $x<y\iff\rho(y)<\rho(x)$. Thus $i$ is a strict minimum of
$w$ iff it is a strict maximum of $\rho\cdot w$. Since $\rho(\rho(x))=x$, the lift is
its own inverse, hence a bijection.
\end{proof}

\begin{corollary}[Equinumerosity]\label{cor:equi}
The number of assignments with a strict maximum equals the number with a strict
minimum.
\end{corollary}

\begin{theorem}[Co-singleton tightness]\label{thm:cosingleton}
The number of isolating assignments for the co-singleton hypergraph with zero
offsets---equivalently, the number of assignments with a unique strict maximum---is
exactly $n\sum_{j=0}^{d-1} j^{\,n-1}=\Bnd$.
\end{theorem}
\begin{proof}
By the reduction, co-singleton isolating assignments are exactly those with a strict
maximum. By Corollary~\ref{cor:equi} these are equinumerous with the strict-minimum
assignments, which number $\Bnd$ by Theorem~\ref{thm:singleton}.
\end{proof}

\section{Discussion}

Theorem~\ref{thm:fails} shows that the freedom of real offsets does not confer
universality: over-counting hypergraphs remain over-counting for every offset.
Extremality is a structural property of the hypergraph, not something achievable by
weighting. Theorems~\ref{thm:singleton} and~\ref{thm:cosingleton} exhibit two
extremal witnesses---the $1$-uniform and $(n-1)$-uniform complete families---related
by the involution $\rho$, suggesting that extremal families come in dual pairs
governed by symmetry. Since $\Bnd$ controls the randomness budget of the Isolation
Lemma, tightness for these families certifies the analysis is best-possible for
them, while the failure of general tightness certifies that many set systems are
strictly more isolation-rich than the floor.

\section{Future directions}

\begin{itemize}
  \item \textbf{Characterise the extremal hypergraphs.} For $n=3$, computation shows
        exactly the singletons and the all-pairs (co-singleton) families reach the
        bound. Conjecture: for the offset-free problem, an antichain attains $\Bnd$
        iff it is vertex-transitive and ``sum-symmetric.'' A formal characterisation
        is open.
  \item \textbf{Covering antichains still fail.} Even covering antichains such as
        $\{\{1,2\},\{1,3\}\}$ overshoot the bound for every offset (verified
        computationally, excess $\ge 1$). A proof quantifying over all real offsets
        would strengthen Theorem~\ref{thm:fails}; the obstacle is reducing the
        continuum of offsets to the finite set of order-types.
  \item \textbf{Intermediate $k$-uniform families.} Singletons ($k=1$) and
        co-singletons ($k=n-1$) are extremal. Are complete $k$-uniform families
        extremal for intermediate $k$? Preliminary data suggests not in general.
  \item \textbf{Quantitative excess.} Define
        $\mathrm{excess}(H)=\min_f \#\mathrm{isolating}(H,f)-\Bnd\ge 0$.
        Understanding $\mathrm{excess}$ as a hypergraph invariant (monotonicity,
        additivity under disjoint unions) is an appealing direction.
\end{itemize}

\section{Conclusion}

The region bound $\Bnd=n\sum_{j=0}^{d-1} j^{\,n-1}$ for isolating weight assignments
of inclusion-free hypergraphs is attained exactly by two symmetric families---the
singletons and their complements---but not universally: no choice of real offsets
can make an over-counting hypergraph extremal, as the frozen count $d^n$ of a single
edge demonstrates. Tightness is a special structural property, and mapping out the
full set of extremal families is the central open problem left in its wake.

