"""Exact verification: singleton and co-singleton families both hit the bound."""
from itertools import product
from typing import Iterable, Tuple

Assignment = Tuple[int, ...]


def region_bound(n: int, d: int) -> int:
    return n * sum(j ** (n - 1) for j in range(d))


def assignments(n: int, d: int) -> Iterable[Assignment]:
    return product(range(d), repeat=n)


def count_strict_min(n: int, d: int) -> int:
    return sum(1 for w in assignments(n, d) if w.count(min(w)) == 1)


def count_strict_max(n: int, d: int) -> int:
    return sum(1 for w in assignments(n, d) if w.count(max(w)) == 1)


for n in range(2, 5):
    for d in range(2, 5):
        B = region_bound(n, d)
        assert count_strict_min(n, d) == B, (n, d)
        assert count_strict_max(n, d) == B, (n, d)
        print(f"n={n} d={d}: strict_min = strict_max = B(n,d) = {B}")

"""Reflection duality made explicit: the map w -> (d-1-w) swaps min and max."""
from itertools import product
from typing import Tuple

Assignment = Tuple[int, ...]


def reflect(w: Assignment, d: int) -> Assignment:
    return tuple(d - 1 - x for x in w)


def has_strict_min(w: Assignment) -> bool:
    return w.count(min(w)) == 1


def has_strict_max(w: Assignment) -> bool:
    return w.count(max(w)) == 1


n, d = 3, 4
strict_min = [w for w in product(range(d), repeat=n) if has_strict_min(w)]
image = {reflect(w, d) for w in strict_min}
strict_max = {w for w in product(range(d), repeat=n) if has_strict_max(w)}
print(f"n={n} d={d}")
print(f"  #strict_min = {len(strict_min)}")
print(f"  reflection image == strict_max set: {image == strict_max}")
print(f"  reflection is an involution: "
      f"{all(reflect(reflect(w, d), d) == w for w in strict_min)}")

