from typing import List


def region_bound(n: int, d: int) -> int:
    """Return B(n, d) = n * sum_{j=0}^{d-1} j^(n-1)."""
    return n * sum(j ** (n - 1) for j in range(d))


def region_bound_table(max_n: int, max_d: int) -> List[List[int]]:
    """Return the table [B(n, d)] for 1 <= n <= max_n, 1 <= d <= max_d."""
    return [[region_bound(n, d) for d in range(1, max_d + 1)]
            for n in range(1, max_n + 1)]

