    total <- 0
    for each w in {0,...,d-1}^n:
        weights <- [ f(S) + sum_{v in S} w[v]  for S in H ]
        m <- min(weights)
        if weights contains m exactly once:
            total <- total + 1
    return total

function REFLECTION_BIJECTION(n, d):
    bij <- empty map
    for each w in {0,...,d-1}^n:
        if w has a unique strict minimum:
            bij[w] <- ( d-1-w[0], ..., d-1-w[n-1] )
    return bij
